{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table sleepycat_db.maplemonk.dwh_Shopify_kaya_UTM_Parameters as select ShopifyQL.* ,upper((UTM_MAPPING.CHANNEL)) as ShopifyQL_MAPPED_CHANNEL ,upper((UTM_MAPPING.UTM_SOURCE)) as ShopifyQL_MAPPED_SOURCE from (select * from (select trim(replace(A.id,\'gid://shopify/Order/\',\'\')) as id ,A.name ,A.createdat ,coalesce(CUSTOMERJOURNEYSUMMARY:\"momentsCount\":\"count\" ,customerjourneysummary:\"momentsCount\") Moments_Count ,replace(A.customerjourneysummary:\"daysToConversion\",\'\"\',\'\') DaysToConvert ,replace(A.CUSTOMERJOURNEYSUMMARY:\"lastVisit\":\"utmParameters\":\"source\",\'\"\',\'\') LastVisit_UTM_Source ,replace(A.CUSTOMERJOURNEYSUMMARY:\"lastVisit\":\"utmParameters\":\"medium\",\'\"\',\'\') LastVisit_UTM_Medium ,replace(A.CUSTOMERJOURNEYSUMMARY:\"lastVisit\":\"source\",\'\"\',\'\') LastVisit_NON_UTM_Source ,replace(A.CUSTOMERJOURNEYSUMMARY:\"lastVisit\":\"utmParameters\":\"campaign\",\'\"\',\'\') LastVisit_UTM_Campaign ,replace(A.CUSTOMERJOURNEYSUMMARY:\"firstVisit\":\"utmParameters\":\"source\",\'\"\',\'\') FirstVisit_UTM_Source ,replace(A.CUSTOMERJOURNEYSUMMARY:\"firstVisit\":\"utmParameters\":\"medium\",\'\"\',\'\') FirstVisit_UTM_Medium ,replace(A.CUSTOMERJOURNEYSUMMARY:\"firstVisit\":\"utmParameters\":\"campaign\",\'\"\',\'\') FirstVisit_UTM_Campaign ,replace(B.Value:\"id\",\'gid://shopify/CustomerVisit/\',\'\') Moment_ID ,replace(B.value:\"utmParameters\":\"source\",\'\"\',\'\') Last_Moment_UTM_Source ,replace(B.value:\"utmParameters\":\"medium\",\'\"\',\'\') Last_Moment_UTM_Medium ,replace(B.value:\"utmParameters\":\"campaign\",\'\"\',\'\') Last_Moment_UTM_Campaign ,case when Moments_Count >1 then LastVisit_UTM_Source else FirstVisit_UTM_Source end CJSummary_utm_source ,referrerdisplaytext Referrer_Name ,customerjourneysummary ,customerjourney ,coalesce(Last_Moment_UTM_Source,LastVisit_UTM_Source) ShopifyQL_Unmapped_Last_Source ,coalesce(Last_Moment_UTM_Medium,LastVisit_UTM_Medium) ShopifyQL_Unmapped_Last_Medium ,coalesce(Last_Moment_UTM_Campaign,LastVisit_UTM_Campaign) ShopifyQL_Unmapped_Last_Campaign ,rank() over (partition by name order by MOMENT_ID desc) rw from sleepycat_db.maplemonk.Sleepycat_db_UTM_PARAMETERS A, lateral flatten (INPUT => customerjourney:\"moments\",OUTER => TRUE) B ) where rw=1 ) ShopifyQL left join ( select * from ( select *, row_number() over (partition by lower(concat(lower(ifnull(utm_source,\'\')),lower(ifnull(utm_medium,\'\')))) order by 1) rw from (select utm_source,utm_medium,source,channel from sleepycat_db.MAPLEMONK.utm_mapping union all select ga_source,ga_medium,final_source,final_channel from sleepycat_db.maplemonk.ga_channel_mapping ) ) where rw=1 and lower(concat(ifnull(utm_source,\'\'),ifnull(utm_medium,\'\'))) is not null ) UTM_MAPPING on replace(lower(concat(ifnull(trim(ShopifyQL.ShopifyQL_Unmapped_Last_Source),\'\'),ifnull(trim(ShopifyQL_Unmapped_Last_Medium),\'\'))),\' \',\'\') = replace(lower(concat(ifnull(UTM_MAPPING.utm_source,\'\'),ifnull(UTM_MAPPING.utm_medium,\'\'))),\' \',\'\') ; create or replace table sleepycat_db.maplemonk.sleepycat_db_GOKWIK_SOURCE as With GO_KWIK as ( WITH utm_source_cte AS ( SELECT S.id, UPPER(A.value:\"value\") AS utm_source FROM sleepycat_db.maplemonk.sleepycat_db_orders S, LATERAL FLATTEN(INPUT => note_attributes) A where (LOWER(S.note_attributes) LIKE ANY (\'%gokwik%\' , \'%razorpay%\') or LOWER(S.tags) LIKE ANY (\'%gokwik%\' , \'%razorpay%\')) AND LOWER(A.value:\"name\") = \'utm_source\' ), utm_medium_cte AS ( SELECT S.id, UPPER(A.value:\"value\") AS utm_medium FROM sleepycat_db.maplemonk.sleepycat_db_orders S, LATERAL FLATTEN(INPUT => note_attributes) A where (LOWER(S.note_attributes) LIKE ANY (\'%gokwik%\' , \'%razorpay%\') or LOWER(S.tags) LIKE ANY (\'%gokwik%\' , \'%razorpay%\')) AND LOWER(A.value:\"name\") = \'utm_medium\' ), utm_campaign_cte AS ( SELECT S.id, UPPER(A.value:\"value\") AS utm_campaign FROM sleepycat_db.maplemonk.sleepycat_db_orders S, LATERAL FLATTEN(INPUT => note_attributes) A where (LOWER(S.note_attributes) LIKE ANY (\'%gokwik%\' , \'%razorpay%\') or LOWER(S.tags) LIKE ANY (\'%gokwik%\' , \'%razorpay%\')) AND LOWER(A.value:\"name\") = \'utm_campaign\' ), utm_content_cte AS ( SELECT S.id ,UPPER(A.value:\"value\") AS utm_content FROM sleepycat_db.maplemonk.sleepycat_db_orders S, LATERAL FLATTEN(INPUT => note_attributes) A where (LOWER(S.note_attributes) LIKE ANY (\'%gokwik%\' , \'%razorpay%\') or LOWER(S.tags) LIKE ANY (\'%gokwik%\' , \'%razorpay%\')) AND LOWER(A.value:\"name\") = \'utm_content\' ) SELECT S.id, S.tags, source_cte.utm_source AS GOKWIK_UTM_SOURCE, medium_cte.utm_medium AS GOKWIK_UTM_MEDIUM, campaign_cte.utm_campaign AS GOKWIK_UTM_CAMPAIGN, content_cte.utm_content AS GOKWIK_UTM_CONTENT FROM sleepycat_db.maplemonk.sleepycat_db_orders S LEFT JOIN utm_source_cte source_cte ON S.id = source_cte.id LEFT JOIN utm_medium_cte medium_cte ON S.id = medium_cte.id LEFT JOIN utm_campaign_cte campaign_cte ON S.id = campaign_cte.id LEFT JOIN utm_content_cte content_cte ON S.id = content_cte.id WHERE LOWER(S.note_attributes) LIKE ANY (\'%gokwik%\',\'%razorpay%\') ) Select GO_KWIK.* ,(Upper(UTM_MAPPING.CHANNEL)) as GOKWIK_MAPPED_CHANNEL ,(Upper(UTM_MAPPING.SOURCE)) as GOKWIK_MAPPED_SOURCE from GO_KWIK left join ( select * from ( select *, row_number() over (partition by lower(concat(lower(ifnull(utm_source,\'\')),lower(ifnull(utm_medium,\'\')))) order by 1) rw from(select utm_source,utm_medium,source,channel from sleepycat_db.MAPLEMONK.utm_mapping union all select ga_source,ga_medium,final_source,final_channel from sleepycat_db.maplemonk.ga_channel_mapping ) ) where rw=1 and lower(concat(ifnull(utm_source,\'\'),ifnull(utm_medium,\'\'))) is not null ) UTM_MAPPING on replace(lower(concat(ifnull(GO_KWIK.GOKWIK_UTM_SOURCE,\'\'),ifnull(GO_KWIK.GOKWIK_UTM_MEDIUM,\'\'))),\' \',\'\') = replace(lower(concat(ifnull(UTM_MAPPING.UTM_SOURCE,\'\'),ifnull(UTM_MAPPING.utm_medium,\'\'))),\' \',\'\') ; create or replace table sleepycat_db.maplemonk.dwh_Shopify_All_orders as select AO.* ,coalesce(GOKWIK_UTM_SOURCE,ShopifyQL_Unmapped_Last_Source) as SHopify_UTM_Source ,coalesce(GOKWIK_UTM_MEDIUM,ShopifyQL_Unmapped_Last_Medium) as SHopify_UTM_Medium ,UPPER(ShopifyQL.shopifyql_mapped_channel) shopifyql_mapped_channel ,UPPER(ShopifyQL.shopifyql_mapped_source) shopifyql_mapped_source ,UPPER(ShopifyQL.FIRSTVISIT_UTM_SOURCE) Shopifyql_FIRSTVISIT_UTM_SOURCE ,UPPER(ShopifyQL.FirstVisit_UTM_Campaign) Shopifyql_FIRSTVISIT_UTM_CAMPAIGN ,upper(ShopifyQL.LastVisit_UTM_Campaign) Shopifyql_LAST_VISIT_UTM_CAMPAIGN ,UPPER(ShopifyQL.LAST_MOMENT_UTM_SOURCE) Shopifyql_LAST_MOMENT_UTM_SOURCE ,UPPER(ShopifyQL.LastVisit_NON_UTM_Source) Shopifyql_LAST_VISIT_NON_UTM_SOURCE ,UPPER(ShopifyQL.LAST_MOMENT_UTM_MEDIUM) Shopifyql_LAST_MOMENT_UTM_MEDIUM ,UPPER(ShopifyQL.FIRSTVISIT_UTM_MEDIUM) Shopifyql_FIRSTVISIT_UTM_MEDIUM ,div0(ShopifyQL.MOMENTS_COUNT,count(1) over (partition by AO.name order by 1)) MOMENTS_COUNT ,div0(ShopifyQL.DAYSTOCONVERT,count(1) over (partition by AO.name order by 1)) DAYSTOCONVERT ,UPPER(GOKWIK.GOKWIK_UTM_SOURCE) GOKWIK_UTM_SOURCE ,UPPER(GOKWIK.GOKWIK_UTM_MEDIUM) GOKWIK_UTM_MEDIUM ,UPPER(GOKWIK.GOKWIK_UTM_CONTENT) GOKWIK_UTM_CONTENT ,UPPER(GOKWIK.GOKWIK_MAPPED_CHANNEL) GOKWIK_MAPPED_CHANNEL ,UPPER(GOKWIK.GOKWIK_MAPPED_SOURCE) GOKWIK_MAPPED_SOURCE ,UPPER(Referrer_Name) Referrer_Name ,UPPER(GOKWIK.GOKWIK_UTM_CAMPAIGN) GOKWIK_UTM_CAMPAIGN ,Upper(coalesce(GOKWIK_MAPPED_SOURCE,shopifyql_mapped_source,\'Direct\')) FINAL_UTM_SOURCE ,Upper(coalesce(GOKWIK_MAPPED_CHANNEL,shopifyql_mapped_channel,\'Direct\')) FINAL_UTM_CHANNEL , row_number() over (partition by ao.name order by 1 ) rw ,case when Upper(coalesce(GOKWIK_MAPPED_CHANNEL,shopifyql_mapped_channel)) is null then 0 else 1 end as UTM_Flag from (select * ,\'Shopify_Sleepycat\' AS Shop_Name from sleepycat_db.maplemonk.sleepycat_db_orders) AO left join (select * from (select *, row_number() over (partition by name order by 1) rwb from sleepycat_db.maplemonk.dwh_Shopify_kaya_UTM_Parameters ) where rwb = 1) ShopifyQL on AO.name = ShopifyQL.name left join sleepycat_db.maplemonk.sleepycat_db_GOKWIK_SOURCE GOKWIK on AO.ID = GOKWIK.ID ; CREATE OR REPLACE TABLE SLEEPYCAT_DB.MAPLEMONK.Shopify_All_products AS select *,\'Shopify\' AS Shop_Name from sleepycat_db.maplemonk.sleepycat_db_products ; CREATE OR REPLACE TABLE SLEEPYCAT_DB.MAPLEMONK.Shopify_All_products_variants AS select *,\'Shopify\' AS Shop_Name from sleepycat_db.maplemonk.sleepycat_db_products_variants ; CREATE OR REPLACE TABLE SLEEPYCAT_DB.MAPLEMONK.Shopify_All_customers_addresses AS select *,\'Shopify\' AS Shop_Name from sleepycat_db.maplemonk.sleepycat_db_customers ; CREATE OR REPLACE TABLE SLEEPYCAT_DB.MAPLEMONK.Shopify_All_orders_items_discount AS SELECT order_id, LINE_ITEM_ID, SUM(B.VALUE:amount::FLOAT) AS DISCOUNT FROM( SELECT id AS order_id, A.VALUE:id AS LINE_ITEM_ID, A.VALUE:discount_allocations AS discount_allocations FROM SLEEPYCAT_DB.MAPLEMONK.dwh_Shopify_All_orders, LATERAL FLATTEN (INPUT => LINE_ITEMS)A)x,LATERAL FLATTEN (INPUT => x.discount_allocations)B GROUP BY ORDER_ID, LINE_ITEM_ID; CREATE OR REPLACE TABLE SLEEPYCAT_DB.MAPLEMONK.Shopify_All_orders_items_tax AS SELECT order_id, LINE_ITEM_ID, SUM(B.VALUE:price::FLOAT) AS TAX, SUM(B.VALUE:rate::float) as Tax_Rate FROM( SELECT id AS order_id, A.VALUE:id AS LINE_ITEM_ID, A.VALUE:tax_lines AS tax_lines FROM SLEEPYCAT_DB.MAPLEMONK.dwh_Shopify_All_orders, LATERAL FLATTEN (INPUT => LINE_ITEMS)A)x,LATERAL FLATTEN (INPUT => x.tax_lines)B GROUP BY order_id, LINE_ITEM_ID; CREATE OR REPLACE TABLE SLEEPYCAT_DB.MAPLEMONK.Shopify_All_Refunds AS WITH refund_line_items AS ( SELECT refunds.value:order_id::STRING AS order_id, line_items.value:line_item_id::string as LINE_ITEM_ID, try_to_timestamp(replace(refunds.value:\"created_at\",\'\"\',\'\')) AS refund_date, sum(ifnull(line_items.value:quantity::INT,0)) AS refund_quantity, sum(ifnull(line_items.value:subtotal::FLOAT,0)) AS refund_subtotal FROM SLEEPYCAT_DB.MAPLEMONK.dwh_Shopify_All_orders, LATERAL FLATTEN(input => dwh_Shopify_All_orders.refunds) refunds, LATERAL FLATTEN(input => refunds.value:refund_line_items) line_items group by refunds.value:order_id::STRING, line_items.value:line_item_id::string, try_to_timestamp(replace(refunds.value:\"created_at\",\'\"\',\'\')) ), order_adjustments AS ( SELECT order_adj.value:order_id::STRING AS order_id, try_to_timestamp(replace(refunds.value:\"created_at\",\'\"\',\'\')) adjustment_date, sum(ifnull(order_adj.value:amount::FLOAT,0)) AS adjustment FROM SLEEPYCAT_DB.MAPLEMONK.dwh_Shopify_All_orders, LATERAL FLATTEN(input => dwh_Shopify_All_orders.refunds) refunds, LATERAL FLATTEN(input => refunds.value:order_adjustments) order_adj group by order_adj.value:order_id::STRING, try_to_timestamp(replace(refunds.value:\"created_at\",\'\"\',\'\')) ), adj_refund as ( Select distinct order_id, line_item_id, date from ( select coalesce(rl.order_id,oa.order_id) order_id, rl.line_item_id, case when rl.refund_date = oa.adjustment_date then rl.refund_date else coalesce(oa.adjustment_date, rl.refund_date) end as date from refund_line_items rl full outer join order_adjustments oa on rl.order_id = oa.order_id ) ), refund_summary as ( select ar.order_id, ar.line_item_id, ar.date, ifnull(rl.refund_quantity,0) refund_quantity, ifnull(rl.refund_subtotal,0) refund_subtotal, ifnull(div0(oa.adjustment,count(1) over (partition by ar.order_id, ar.date)),0) as Adjustment_amount, (ifnull(rl.refund_subtotal,0) - ifnull(Adjustment_amount,0)) Total_Refund from adj_refund ar left join refund_line_items rl on ar.order_id = rl.order_id and ar.date = rl.refund_date and ar.line_item_id = rl.line_item_id left join order_adjustments oa on ar.order_id = oa.order_id and ar.date = oa.adjustment_date ), aggregate_summary AS ( SELECT order_id, line_item_id, date, sum(refund_quantity) AS Refund_Quantity, sum(Total_Refund) AS Refund_Amount, sum(Adjustment_amount) AS Adjustment_Amount, sum(refund_subtotal) AS Refund_Before_Adjustment FROM refund_summary GROUP BY order_id, line_item_id, date ) SELECT asum.order_id, min(asum.date) as refund_date, asum.line_item_id, sum(asum.Refund_Quantity) Quantity, sum(asum.Refund_Amount) Amount, sum(asum.Adjustment_Amount) Adjustment_Amount, sum(asum.Refund_Before_Adjustment) Refund_Before_Adjustment, ARRAY_AGG( Object_construct( \'Refund_Date\', asum.date, \'Refund_Quantity\', ifnull(to_varchar(CAST(asum.Refund_Quantity AS DECIMAL(38,2))), \'0\'), \'Adjustment_Amount\', ifnull(to_varchar(CAST(asum.Adjustment_Amount AS DECIMAL(38,2))), \'0\'), \'Refund_Amount\', ifnull(to_varchar(CAST(asum.Refund_Amount AS DECIMAL(38,2))), \'0\') ) ) AS Refund_Details FROM aggregate_summary asum GROUP BY asum.order_id, asum.line_item_id; CREATE OR REPLACE TABLE SLEEPYCAT_DB.MAPLEMONK.Shopify_All_orders_fulfillment AS SELECT A.value:order_id AS order_id, B.value:id Line_Item_ID, replace(A.VALUE:tracking_number,\'\"\',\'\') as AWB, Upper(replace(A.VALUE:tracking_company,\'\"\',\'\')) as Courier, Upper(replace(A.VALUE:shipment_status,\'\"\',\'\')) as Shipping_status, replace(A.VALUE:updated_at,\'\"\',\'\') as shipping_status_update_date, replace(A.VALUE:tracking_url,\'\"\',\'\') as tracking_url, replace(A.VALUE:created_at,\'\"\',\'\') as Shipping_created_at FROM SLEEPYCAT_DB.MAPLEMONK.dwh_Shopify_All_orders, LATERAL FLATTEN (INPUT => fulfillments)A,LATERAL FLATTEN (INPUT => A.value:line_items)B; create or replace table SLEEPYCAT_DB.MAPLEMONK.Shopify_All_orders_shipping_lines_discount as SELECT id as Order_ID, SUM(ifnull(CAST(da.value:amount AS FLOAT),0)) AS total_shipping_discount FROM SLEEPYCAT_DB.MAPLEMONK.dwh_Shopify_All_orders, LATERAL FLATTEN(input => shipping_lines) AS sl, LATERAL FLATTEN(input => sl.value:discount_allocations) AS da group by 1; CREATE OR REPLACE TABLE SLEEPYCAT_DB.MAPLEMONK.Shopify_All_orders_items AS WITH CTE AS (SELECT SHOP_NAME, ID::VARCHAR(16777216) AS ORDER_ID, NAME AS ORDER_NAME, CUSTOMER, replace(customer:default_address:name,\'\"\',\'\') NAME, PHONE, EMAIL, tags, A.VALUE:id AS LINE_ITEM_ID, A.VALUE:sku::STRING AS SKU, A.VALUE:product_id::STRING AS PRODUCT_ID, upper(A.VALUE:title::STRING) AS PRODUCT_NAME, CURRENCY, CASE WHEN cancelled_at IS NOT NULL THEN \'CANCELLED\' ELSE \'SHOPIFY_PROCESSED\' END AS order_status, CREATED_AT::DATETIME AS order_timestamp, A.VALUE:price::FLOAT * A.VALUE:quantity::FLOAT AS LINE_ITEM_SALES, (TOTAL_SHIPPING_PRICE_SET:presentment_money:amount::FLOAT/ COUNT(ORDER_ID) OVER(PARTITION BY ORDER_ID ORDER BY ORDER_ID)) AS SHIPPING_PRICE, A.value:price/(1+A.value:tax_lines:rate) PRICE_BEFORE_TAX, A.VALUE:quantity::FLOAT as QUANTITY, \'SHOPIFY\' AS Source, MOMENTS_COUNT, DAYSTOCONVERT, Shopifyql_LAST_VISIT_UTM_CAMPAIGN, Shopifyql_FIRSTVISIT_UTM_CAMPAIGN, SHOPIFYQL_FIRSTVISIT_UTM_SOURCE, SHOPIFYQL_MAPPED_SOURCE, SHOPIFYQL_MAPPED_CHANNEL, SHOPIFYQL_LAST_MOMENT_UTM_SOURCE, Shopifyql_LAST_VISIT_NON_UTM_SOURCE, Shopifyql_LAST_MOMENT_UTM_MEDIUM, Shopifyql_FIRSTVISIT_UTM_MEDIUM, GOKWIK_UTM_SOURCE, GOKWIK_UTM_MEDIUM, GOKWIK_UTM_CAMPAIGN, GOKWIK_UTM_CONTENT, null FINAL_UTM_CAMPAIGN, null FINAL_UTM_CHANNEL, null FINAL_UTM_SOURCE, null UTM_Mapping_Flag, null UTM_Source, null UTM_Medium, Referrer_Name, null CHECKOUT_MAPPED_SOURCE, null CHECKOUT_MAPPED_CHANNEL, payment_gateway_names as GATEWAY, SHIPPING_ADDRESS, case when lower(payment_gateway_names) like any (\'%cod%\',\'%cash%\') then \'COD\' else \'PREPAID\' end payment_mode, APP_ID FROM SLEEPYCAT_DB.MAPLEMONK.dwh_Shopify_All_orders, LATERAL FLATTEN (INPUT => LINE_ITEMS)A) SELECT CTE.*, IFNULL(T.TAX_RATE,0) AS TAX_RATE, IFNULL(D.DISCOUNT,0) AS DISCOUNT, CTE.LINE_ITEM_SALES AS GROSS_SALES_AFTER_TAX, CTE.LINE_ITEM_SALES/(1+IFNULL(T.TAX_RATE,0)) AS GROSS_SALES_BEFORE_TAX, CASE when IFNULL(T.TAX,0)=0 then IFNULL(D.DISCOUNT,0) else IFNULL(D.DISCOUNT,0)/(1+IFNULL(T.TAX_RATE,0)) end AS DISCOUNT_BEFORE_TAX, CASE when IFNULL(T.TAX,0)=0 then CTE.LINE_ITEM_SALES - IFNULL(D.DISCOUNT,0) else CTE.LINE_ITEM_SALES/(1+IFNULL(T.TAX_RATE,0)) - IFNULL(D.DISCOUNT,0)/(1+IFNULL(T.TAX_RATE,0)) end AS NET_SALES_BEFORE_TAX, IFNULL(T.TAX,0) AS TAX, case when IFNULL(T.TAX,0)=0 then (CTE.LINE_ITEM_SALES) - IFNULL(D.DISCOUNT,0) - div0(ifnull(SD.TOTAL_SHIPPING_DISCOUNT,0),count(1) over (partition by CTE.order_id)) + IFNULL(T.TAX,0) + CTE.SHIPPING_PRICE else (CTE.LINE_ITEM_SALES/(1+IFNULL(T.TAX_RATE,0))) - (IFNULL(D.DISCOUNT,0)/(1+IFNULL(T.TAX_RATE,0))) - div0(ifnull(SD.TOTAL_SHIPPING_DISCOUNT,0),count(1) over (partition by CTE.order_id)) + IFNULL(T.TAX,0) + CTE.SHIPPING_PRICE end AS TOTAL_SALES, CASE WHEN R.QUANTITY IS NOT NULL THEN 1 ELSE 0 END AS IS_REFUND, R.REFUND_DETAILS, R.QUANTITY Refund_Quantity, R.AMOUNT Refund_Value, R.Refund_Date, F.AWB, F.Courier, F.Shipping_status, F.shipping_status_update_date, F.tracking_url, F.Shipping_created_at, div0(ifnull(SD.TOTAL_SHIPPING_DISCOUNT,0),count(1) over (partition by CTE.order_id)) TOTAL_SHIPPING_DISCOUNT FROM CTE LEFT JOIN SLEEPYCAT_DB.MAPLEMONK.Shopify_All_orders_items_tax T ON CTE.ORDER_ID = T.ORDER_ID AND CTE.LINE_ITEM_ID = T.LINE_ITEM_ID LEFT JOIN SLEEPYCAT_DB.MAPLEMONK.Shopify_All_orders_items_discount D ON CTE.ORDER_ID = D.ORDER_ID AND CTE.LINE_ITEM_ID = D.LINE_ITEM_ID LEFT JOIN SLEEPYCAT_DB.MAPLEMONK.Shopify_All_Refunds R ON CTE.ORDER_ID = R.ORDER_ID AND CTE.LINE_ITEM_ID = R.LINE_ITEM_ID LEFT JOIN SLEEPYCAT_DB.MAPLEMONK.Shopify_All_orders_fulfillment F ON CTE.ORDER_ID = F.ORDER_ID AND CTE.LINE_ITEM_ID = F.LINE_ITEM_ID LEFT JOIN SLEEPYCAT_DB.MAPLEMONK.Shopify_All_orders_shipping_lines_discount SD ON CTE.ORDER_ID = SD.ORDER_ID;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SLEEPYCAT_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
